// ===== CONFIG: keep identical in 'Tool - Book Appointment (Verified)' =====
const SLOT_MIN = 30;          // fixed appointment length (minutes)
const WORK_START = 10;        // 10:00 IST
const WORK_END = 18;          // 18:00 IST (last slot must END by this)
const WORK_DAYS = [1,2,3,4,5,6]; // Mon-Sat (0 = Sunday)
const DAYS = 7;               // look ahead
const LEAD_HOURS = 2;         // no slots sooner than this
const MAX_SLOTS = 6, MAX_PER_DAY = 3;
// ==========================================================================
const OFFSET = 5.5 * 3600 * 1000; // IST, no DST
const toMs = (x) => x && (x.dateTime ? Date.parse(x.dateTime) : x.date ? Date.parse(x.date + 'T00:00:00+05:30') : NaN);
const busy = $input.all().map(i => i.json)
  .filter(e => e && e.id && e.status !== 'cancelled')
  .map(e => ({ s: toMs(e.start), e: toMs(e.end) }))
  .filter(b => !isNaN(b.s) && !isNaN(b.e));
const now = Date.now(), earliest = now + LEAD_HOURS * 3600e3;
const ist = new Date(now + OFFSET);
const y = ist.getUTCFullYear(), m = ist.getUTCMonth(), d0 = ist.getUTCDate();
const iso = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 19) + '+05:30';
const label = (ms) => new Date(ms).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
const out = [];
for (let d = 0; d <= DAYS && out.length < MAX_SLOTS; d++) {
  if (!WORK_DAYS.includes(new Date(Date.UTC(y, m, d0 + d)).getUTCDay())) continue;
  const free = [];
  for (let mins = WORK_START * 60; mins + SLOT_MIN <= WORK_END * 60; mins += SLOT_MIN) {
    const start = Date.UTC(y, m, d0 + d, 0, mins) - OFFSET, end = start + SLOT_MIN * 60000;
    if (start < earliest) continue;
    if (busy.some(b => b.s < end && b.e > start)) continue;
    free.push({ start_time: iso(start), end_time: iso(end), label: label(start) });
  }
  const pick = free.length <= MAX_PER_DAY ? free : [free[0], free[Math.floor(free.length / 2)], free[free.length - 1]];
  for (const s of pick) if (out.length < MAX_SLOTS) out.push(s);
}
return [{ json: {
  success: true, timezone: 'Asia/Kolkata', slot_length_minutes: SLOT_MIN, available_slots: out,
  message: out.length ? 'Offer ONLY these slots. When booking, pass start_time exactly as given.' : 'No free slots in the next 7 days. Do not invent slots; tell the customer and offer to have the team contact them.'
} }];
